from pathlib import Path
import html,json
from content import CATEGORIES,PROJECTS,BIO,COMPLICE
R=Path(__file__).resolve().parents[1]; esc=html.escape
manifest_path=Path(__file__).with_name('image-manifest.json')
M=json.loads(manifest_path.read_text()) if manifest_path.exists() else {}
def picture(name,alt,prefix='',lazy=True,cls=''):
 loading = 'loading="lazy"' if lazy else 'fetchpriority="high"'
 return f'<img src="{prefix}assets/images/{name}.webp" alt="{esc(alt)}" width="1600" height="1100" {loading} decoding="async" class="{cls}">'
def shell(title,description,body,prefix='',home=False):
 homepath=prefix+'index.html'
 return f'''<!doctype html>
<html lang="de-CH"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f2f0e8"><title>{esc(title)} | Monika Frei</title><meta name="description" content="{esc(description)}"><meta property="og:title" content="{esc(title)} | Monika Frei"><meta property="og:description" content="{esc(description)}"><meta property="og:type" content="website"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/style.css"><script src="{prefix}assets/main.js" defer></script></head>
<body><a class="skip" href="#inhalt">Zum Inhalt springen</a><header class="site-header"><a class="brand" href="{homepath}" aria-label="Monika Frei – Startseite"><span class="brand-mark" aria-hidden="true">✳</span> Monika Frei</a><button class="menu-button" type="button" aria-expanded="false" aria-controls="navigation">Menü <span aria-hidden="true">＋</span></button><nav class="nav" id="navigation" aria-label="Hauptnavigation"><a href="{homepath}#projekte">Theaterprojekte</a><a href="{homepath}#kinderliteratur">Kinderliteratur</a><a href="{prefix}ueber-mich.html">Über mich</a><a href="{homepath}#kontakt">Kontakt ↗</a></nav></header>
<main id="inhalt">{body}</main>
<footer class="footer"><span>© Monika Frei · Theaterpädagogin & Autorin</span><a href="{prefix}projektverzeichnis.html">Projektverzeichnis</a><a href="{prefix}impressum.html">Impressum & Datenschutz</a><a href="#inhalt">Nach oben ↑</a></footer></body></html>'''
def contact(prefix=''):
 return '''<section class="contact wrap" id="kontakt"><div class="contact-top"><p class="eyebrow">Kontakt / Eine Idee beginnt im Gespräch.</p><h2>Lass uns etwas<br><em style="font-family:var(--serif);font-weight:400">in Bewegung bringen.</em></h2></div><a class="contact-mail" href="mailto:monikafrei@bluewin.ch">monikafrei@bluewin.ch <span aria-hidden="true">↗</span></a></section>'''
def gallery(key,title,prefix='../'):
 names=M.get(key,{}).get('images',[f'{key}-{n:02d}' for n in range(1,4)])
 return '<div class="gallery wrap">'+''.join(f'<figure><button type="button" data-gallery aria-label="{esc(title)}: Bild {i+1} vergrössern">{picture(n,f"{title} – Projekteinblick {i+1}",prefix)}<span class="zoom-label" aria-hidden="true">＋</span></button><figcaption>{i+1:02d} / {len(names):02d}</figcaption></figure>' for i,n in enumerate(names))+'</div>'
def project_images(p):return M.get(p['id'],{}).get('images',[p['id']+'-01'])
def card(p):
 cat=CATEGORIES[p['cat']]['title']; img=project_images(p)[0]
 return f'''<article class="project-card" data-category="{p['cat']}"><a href="projekte/{p['id']}.html"><div class="card-image">{picture(img,p['title']+' – '+p['context'])}<span class="card-arrow" aria-hidden="true">↗</span></div><div class="card-meta"><span>{cat}</span><span>{p['year']}</span></div><h3>{esc(p['title'])}</h3><p>{esc(p['context'])}</p></a></article>'''
filters=''.join(f'<button class="filter" type="button" data-filter="{key}" aria-pressed="{str(key=="all").lower()}">{name}<span class="filter-count">{len(PROJECTS) if key=="all" else sum(p["cat"]==key for p in PROJECTS)}</span></button>' for key,name in [('all','Alle Projekte'),('forschung','Forschendes Theater'),('schulhaus','Schulhausbespielung'),('buehne','Theaterstücke')])
body=f'''<section class="hero wrap"><div class="hero-line"><p class="eyebrow">Theaterpädagogin & Autorin</p><span class="location">Zürich ↔ Wien</span></div><h1>Theater,<br><span>das bewegt.</span></h1><div class="hero-lower"><div class="hero-note"><p>Gemeinsam forschen.<br>Geschichten erfinden.<br>Neue Spielräume öffnen.</p><a href="#projekte" class="round-link"><span aria-hidden="true">↓</span> Projekte entdecken</a></div><figure class="hero-photo">{picture('hero','Einblick in die Theaterarbeit von Monika Frei',lazy=False)}<figcaption class="photo-tag">Neugier ist der Anfang.</figcaption></figure></div><div class="hero-footer"><span>Theater · Vermittlung · Kinderliteratur</span><span class="small-star" aria-hidden="true">✳</span><span>Raum für Möglichkeiten</span></div></section>
<section class="intro wrap"><p class="eyebrow">Meine Arbeit</p><h2>Ich öffne Räume, in denen wir Fragen stellen, Geschichten erfinden und die Welt <span class="italic">gemeinsam neu denken.</span></h2></section>
<section class="projects wrap" id="projekte"><span class="section-number">01 / Einblicke in die Projektwelt</span><div class="section-heading"><h2>Vom Fragen<br>zum Spielen.</h2><p>Mit Kindern, Jugendlichen und Erwachsenen. In Schulen, auf Bühnen und überall dazwischen.</p></div><div class="filter-bar" role="group" aria-label="Projekte nach Arbeitsbereich filtern">{filters}</div><p class="filter-description"></p><p class="sr-only" id="filter-status" role="status" aria-live="polite">13 Projekte angezeigt</p><div class="project-grid">{''.join(card(p) for p in PROJECTS)}</div><a class="archive-link" href="projektverzeichnis.html"><span>Weitere Arbeiten & Projektverzeichnis</span><span aria-hidden="true">↗</span></a></section>
<section class="complice wrap" id="komplizinnen"><span class="section-number">02 / Miteinander gestalten</span><div class="complice-layout"><div><h2>gemeinsam<br><em>Kompliz:innen</em></h2><p class="eyebrow">Die Schule als Lernort sozialer Kompetenzen</p><p>Wie wollen wir miteinander umgehen? Ein performatives Projekt über Vielfalt, Dialog, Freundschaften und Zusammenleben.</p><div class="actions"><a class="button" href="gemeinsam-komplizinnen.html">Das Projekt kennenlernen <span aria-hidden="true">↗</span></a><a class="button secondary" href="assets/downloads/gemeinsam-komplizinnen.pdf" download>Konzept als PDF <span aria-hidden="true">↓</span></a></div></div><div class="complice-art">{picture('komplizinnen-01','Einblick in gemeinsam Kompliz:innen')}<span class="sticker" aria-hidden="true">Gemeinsam<br>geht mehr.</span></div></div></section>
<section class="literature wrap" id="kinderliteratur"><div><p class="eyebrow">03 / Kinderliteratur</p><h2>Geschichten,<br>die <span class="italic">weiterwirken.</span></h2><p>Ich schreibe Theaterstücke für Kinder und Jugendliche sowie Kinderromane. Im Herzen der Abenteuer stehen die eigene Identität und Integrativität.</p><p>Seit 2014 verfasse ich Theaterstücke, die sich mit sozial- und gesellschaftspolitischen Themen auseinandersetzen und auf die Bühne finden.</p><a class="round-link" href="mailto:monikafrei@bluewin.ch?subject=Anfrage%20Kinderliteratur"><span aria-hidden="true">↗</span> Über Geschichten ins Gespräch kommen</a></div><div class="word-art" aria-hidden="true"><span>Was</span><span>wäre,</span><span>wenn?</span><b>✳</b></div></section>
<section class="about wrap" id="ueber-mich"><figure class="about-image">{picture('portrait','Monika Frei bei der Theaterarbeit')}<figcaption>Aufgewachsen in der Ostschweiz. Zuhause in Zürich und Wien.</figcaption></figure><div><p class="eyebrow">04 / Über mich</p><h2>Monika Frei.<br><span class="italic">Mit Neugier<br>und Haltung.</span></h2><p>Ich bin Theaterpädagogin und Autorin. Ich leite Theaterprojekte und performative Vermittlung für Spieler:innen aller Altersgruppen.</p><p>Meine Arbeit verbindet Theater, Pädagogik und die Lust, gemeinsam neue Perspektiven zu entdecken.</p><a class="round-link" href="ueber-mich.html"><span aria-hidden="true">↗</span> Mehr über mich</a></div></section>'''+contact()
(R/'index.html').write_text(shell('Theater, das bewegt','Monika Frei – Theaterpädagogin und Autorin. Forschendes Theater, Schulhausbespielungen, Inszenierungen und Kinderliteratur.',body),encoding='utf-8')
for i,p in enumerate(PROJECTS):
 imgs=project_images(p);c=CATEGORIES[p['cat']];nxt=PROJECTS[(i+1)%len(PROJECTS)]
 sub=f'<p class="detail-subtitle">{esc(p["subtitle"])}</p>' if p.get('subtitle') else ''
 credit=f'<span>Fotografie: {esc(p["credit"])}</span>' if p['credit'] else ''
 body=f'''<section class="detail-hero wrap"><a class="back" href="../index.html#projekte">← Alle Theaterprojekte</a><p class="eyebrow">{c['title']} / {c['subtitle']}</p><h1>{esc(p['title'])}</h1>{sub}<div class="detail-meta"><span>{esc(p['context'])}</span><span>{p['year']}</span>{credit}</div></section><div class="detail-cover">{picture(imgs[0],p['title']+' – '+p['context'],'../',False)}</div><section class="project-story wrap"><p class="eyebrow">Das Projekt</p><div><p>{esc(p['text'])}</p></div></section>'''+gallery(p['id'],p['title'])+f'''<section class="project-story wrap"><p class="eyebrow">{c['title']}</p><div><p>{c['text']}</p><p>{c['more']}</p><a class="button" href="mailto:monikafrei@bluewin.ch?subject=Anfrage%20Theaterprojekt">Ein Projekt anfragen ↗</a></div></section><a class="next-project wrap" href="{nxt['id']}.html"><div><span class="eyebrow">Nächstes Projekt</span><strong>{esc(nxt['title'])}</strong></div><span class="next-arrow" aria-hidden="true">↗</span></a>'''
 (R/'projekte'/f'{p["id"]}.html').write_text(shell(p['title'],p['text'][:155],body,'../'),encoding='utf-8')
body=f'''<section class="detail-hero wrap"><a class="back" href="index.html#komplizinnen">← Zur Übersicht</a><p class="eyebrow">Performative Praxis / Soziales Lernen</p><h1>gemeinsam<br><span class="italic">Kompliz:innen</span></h1><p class="detail-subtitle">Die Schule als Lernort sozialer Kompetenzen</p><div class="detail-meta"><span>Prävention & Intervention</span><span>Entwickelt 2024</span></div></section><div class="detail-cover">{picture('komplizinnen-01','Gemeinsam Kompliz:innen – Projektarbeit',lazy=False)}</div><section class="project-story wrap"><p class="eyebrow">Das Projekt</p><div>{''.join('<p>'+x+'</p>' for x in COMPLICE)}<div class="actions"><a class="button" href="assets/downloads/gemeinsam-komplizinnen.pdf" download>Konzept herunterladen · PDF ↓</a><a class="button secondary" href="assets/downloads/gemeinsam-komplizinnen.pdf" target="_blank" rel="noopener">PDF ansehen ↗</a></div></div></section>'''+gallery('komplizinnen','gemeinsam Kompliz:innen','')+contact()
(R/'gemeinsam-komplizinnen.html').write_text(shell('gemeinsam Kompliz:innen','Die Schule als Lernort sozialer Kompetenzen. Ein Projekt von Monika Frei für Vielfalt, Dialog und Zusammenleben. Konzept als PDF.',body),encoding='utf-8')
body=f'''<section class="detail-hero wrap"><a class="back" href="index.html">← Zur Startseite</a><p class="eyebrow">Theaterpädagogin & Autorin</p><h1>Monika Frei.<br><span class="italic">Neugierig bleiben.</span></h1></section><section class="bio-layout wrap"><figure>{picture('portrait','Monika Frei bei der Theaterarbeit',lazy=False)}<figcaption>Ostschweizer Wurzeln. Zürich und Wien als Zuhause.</figcaption></figure><div class="prose">{''.join('<p>'+x+'</p>' for x in BIO)}<a href="projektverzeichnis.html" class="button">Zum Projektverzeichnis ↗</a></div></section>'''+contact()
(R/'ueber-mich.html').write_text(shell('Über mich','Monika Frei – Theaterpädagogin und Autorin. Mein Weg zwischen Theater, Vermittlung, Pädagogik und Kinderliteratur.',body),encoding='utf-8')
rows=[('2020–2025','Kursleitung','Bühnerei Winterthur: Bühne frei Minis! (5–7), Kids! (8–12), Youngsters! (13–16), Ensemble (U18) · Bühne Aarau: Spielclub U12 · Theater Metalli, Kinder- und Jugendtheater Zug: Theaterratten (12–15)'),('seit 2024','Gewaltprävention & soziale Arbeit','STIS Programm Schule Zürich: gemeinsam Kompliz:innen · Friendspfeife'),('2024 / 2026','Theaterpädagogisches Engagement','Wohnstätte Zwyssig (2024) · OSS Lengg (2026)'),('seit 2020','Theaterprojekte & Vermittlung','VSA Schule+Kultur Zürich: Toi toi toi! Theaterprojekt in der Schule · Theater Bilitz: Theaterkurse und Workshops für Kinder, Jugendliche und Erwachsene'),('seit 2025','Klassen- und Schulprojekte','Primarschulen in den Kantonen Thurgau und Zürich'),('2020–2022','REST-ZEIT-STORY-SORRY','Kollektiv der Künste · Schauspielhaus Zürich, 2022'),('2018/2019','Apropos… Urknall','Schauspielhaus Zürich · Regieassistenz'),('2021/2022','Weihnachtsgeschichte','Arche Zürich'),('2020/2021','Die Gefahr droht im All · Anker hoch!','Primarschule Buchwiesen, Zürich'),('2019/2020','Einmal · Piratentochter Rosa','Primarschule Buchwiesen, Zürich'),('2018/2019','Momo (nach Michael Ende)','Primarschule Buchwiesen, Zürich'),('2018','Rowet','Lipdub-Schulprojekt · 5. Klasse, Zürich · mit einem eigenen Song aus den Geschichten der Schüler:innen'),('2017','Die toten Socken','Musiktheater · 5. Klasse, Zürich · mit Livemusik während der Aufführung'),('2017/2018','Die unglaubliche Reise von Herrn Rowet · Das Geheimnis um die verschwundenen Wörter','Primarschule Buchwiesen, Zürich'),('2017/2018','Felix Zürich geht auf Weltreise','Kindergarten Caspar-Wüst, Zürich'),('2015/2016','Tage wie diese · Kinder der Welt','Primarschule Buchwiesen, Zürich'),('2014/2015','Let it go','Primarschule Buchwiesen, Zürich'),('2013/2014','Detektive und ihre Geschichten','Primarschule Breite, Sirnach'),('2011/2012','Don’t stop me now!','Primarschule Erlenbach'),('2010/2011','Jim Knopf und Lukas der Lokomotivführer (nach Michael Ende)','Primarschule Erlenbach')]
body='''<section class="detail-hero wrap"><a class="back" href="index.html#projekte">← Zur Projektübersicht</a><p class="eyebrow">Arbeiten & Zusammenarbeit</p><h1>Projektverzeichnis</h1></section><section class="archive wrap"><h2>Projekte mit Einblicken</h2>'''
body+=''.join(f'<div class="archive-row"><span>{p["year"]}</span><p><a href="projekte/{p["id"]}.html">{esc(p["title"])} ↗</a><small>{esc(p["context"])}</small></p></div>' for p in PROJECTS)
body+='<h2>Kursleitung, Engagement & weitere Arbeiten</h2>'+''.join(f'<div class="archive-row"><span>{y}</span><p>{t}<small>{c}</small></p></div>' for y,t,c in rows)+'</section>'+contact()
(R/'projektverzeichnis.html').write_text(shell('Projektverzeichnis','Theaterprojekte, Kursleitungen und Inszenierungen von Monika Frei seit 2010.',body),encoding='utf-8')
body='''<section class="detail-hero wrap"><a class="back" href="index.html">← Zur Startseite</a><h1>Impressum<br>& Datenschutz</h1></section><section class="legal wrap"><h2>Verantwortlich für diese Website</h2><p>Monika Frei<br>8003 Zürich<br>Schweiz</p><p><a href="mailto:monikafrei@bluewin.ch">monikafrei@bluewin.ch</a></p><h2>Inhalt</h2><p>Diese Website dient der persönlichen Vorstellung und der Information über meine Tätigkeiten als Theaterpädagogin und Autorin. Bei Interesse an einer Zusammenarbeit freue ich mich über eine Nachricht.</p><h2>Urheberrecht & Bildnachweise</h2><p>Die veröffentlichten Texte, Bilder und Werke sind urheberrechtlich geschützt. Eine Verwendung bedarf der Zustimmung der jeweiligen Rechteinhaber:innen. Die bekannten Fotograf:innen sind auf den Projektseiten genannt.</p><h2>Technik & Datenschutz</h2><p>Diese Website verwendet keine Analysewerkzeuge, keine Werbetracker und keine Cookies. Schriften, Bilder und Skripte werden zusammen mit der Website ausgeliefert. Es werden keine externen Schrift- oder Mediendienste eingebunden.</p><p>Die Website ist für die Bereitstellung über GitHub Pages vorbereitet. Beim Abruf kann der Hostinganbieter technische Verbindungsdaten verarbeiten. Informationen dazu stellt GitHub in seiner Datenschutzerklärung bereit.</p><p><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noopener">Datenschutzerklärung von GitHub ↗</a></p><h2>Kontakt per E-Mail</h2><p>Bei einer Kontaktaufnahme per E-Mail verwende ich die mitgeteilten Angaben zur Bearbeitung der Anfrage. Die E-Mail-Links öffnen das auf deinem Gerät eingerichtete E-Mail-Programm.</p></section>'''
(R/'impressum.html').write_text(shell('Impressum & Datenschutz','Kontakt, Verantwortlichkeit, Bildnachweise und Informationen zur Technik dieser Website.',body),encoding='utf-8')
(R/'.nojekyll').write_text('')
